package com.example.banking.service;
import com.example.banking.dto.ApiDtos.AccountView; import com.example.banking.entity.*; import com.example.banking.exception.ApiException; import com.example.banking.repository.*; import java.math.BigInteger; import java.security.SecureRandom; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AccountService {
 private final AccountRepository accounts; private final UserRepository users; private final AuditRepository audits; private final SecureRandom random=new SecureRandom();
 public AccountService(AccountRepository accounts,UserRepository users,AuditRepository audits){this.accounts=accounts;this.users=users;this.audits=audits;}
 @Transactional public AccountView create(String email){AppUser owner=users.findByEmail(email).orElseThrow(()->ApiException.notFound("User not found"));String number;do{byte[] entropy=new byte[8];random.nextBytes(entropy);number="10"+String.format(Locale.ROOT,"%016d",new BigInteger(1,entropy).mod(BigInteger.TEN.pow(16)).longValueExact());}while(accounts.findByAccountNumber(number).isPresent());BankAccount a=accounts.save(new BankAccount(number,owner));audits.save(new AuditLog(owner.getId(),"ACCOUNT_CREATED",number));return view(a);}
 @Transactional(readOnly=true) public List<AccountView> list(String email){AppUser u=users.findByEmail(email).orElseThrow(()->ApiException.notFound("User not found"));return accounts.findByOwnerId(u.getId()).stream().map(AccountService::view).toList();}
 @Transactional(readOnly=true) public AccountView get(Long id,String email,boolean admin){BankAccount a=accounts.findById(id).orElseThrow(()->ApiException.notFound("Account not found"));if(!admin&&!a.getOwner().getEmail().equals(email))throw ApiException.forbidden("Account access denied");return view(a);}
 @Transactional public AccountView status(Long id,AccountStatus status,Long actor){BankAccount a=accounts.lockById(id).orElseThrow(()->ApiException.notFound("Account not found"));if(a.getStatus()==AccountStatus.CLOSED&&status!=AccountStatus.CLOSED)throw ApiException.badRequest("Closed accounts cannot be reactivated");if(status==AccountStatus.CLOSED&&a.getBalance().signum()!=0)throw ApiException.badRequest("Transfer or withdraw the remaining balance before closing the account");a.setStatus(status);audits.save(new AuditLog(actor,"ACCOUNT_STATUS_CHANGED",a.getAccountNumber()+":"+status));return view(a);}
 public static AccountView view(BankAccount a){return new AccountView(a.getId(),a.getAccountNumber(),a.getBalance(),a.getStatus(),a.getCreatedAt());}
}
